package com.exampro.service;
import com.exampro.dto.ApiDtos.*;import com.exampro.entity.*;import com.exampro.exception.*;import com.exampro.repository.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.util.*;
@Service @Transactional public class QuestionService {private final QuestionRepository questions;private final SubjectRepository subjects;public QuestionService(QuestionRepository q,SubjectRepository s){questions=q;subjects=s;}public List<QuestionResponse> all(){return questions.findAll().stream().map(q->dto(q,false)).toList();}public QuestionResponse get(Long id){return dto(questions.findById(id).orElseThrow(()->new NotFoundException("Question not found")),false);}
 @Transactional public QuestionResponse create(QuestionRequest r){long correct=r.options().stream().filter(OptionRequest::correct).count();if(correct!=1)throw new BadRequestException("Exactly one option must be marked correct");Subject sub=subjects.findById(r.subjectId()).orElseThrow(()->new NotFoundException("Subject not found"));Question q=new Question();q.setText(r.text());q.setSubject(sub);q.setDifficulty(r.difficulty());q.setMarks(r.marks());for(OptionRequest o:r.options()){QuestionOption op=new QuestionOption();op.setText(o.text());op.setCorrect(o.correct());q.addOption(op);}return dto(questions.save(q),true);}
 @Transactional public QuestionResponse update(Long id,QuestionRequest r){Question q=questions.findById(id).orElseThrow(()->new NotFoundException("Question not found"));if(r.options().stream().filter(OptionRequest::correct).count()!=1)throw new BadRequestException("Exactly one option must be marked correct");q.setText(r.text());q.setDifficulty(r.difficulty());q.setMarks(r.marks());q.setSubject(subjects.findById(r.subjectId()).orElseThrow(()->new NotFoundException("Subject not found")));q.getOptions().clear();for(OptionRequest o:r.options()){QuestionOption op=new QuestionOption();op.setText(o.text());op.setCorrect(o.correct());q.addOption(op);}return dto(questions.save(q),true);}
 public void delete(Long id){Question q=questions.findById(id).orElseThrow(()->new NotFoundException("Question not found"));if(!q.getOptions().isEmpty()){}questions.delete(q);}
 public QuestionResponse dto(Question q,boolean admin){return new QuestionResponse(q.getId(),q.getText(),q.getDifficulty().name(),q.getMarks(),q.getSubject().getId(),q.getSubject().getName(),q.getOptions().stream().map(o->new OptionResponse(o.getId(),o.getText())).toList());}
 public List<AdminQuestionResponse> adminAll(){return questions.findAll().stream().map(this::adminDto).toList();}
 public AdminQuestionResponse adminGet(Long id){return adminDto(questions.findById(id).orElseThrow(()->new NotFoundException("Question not found")));}
 public AdminQuestionResponse adminDto(Question q){return new AdminQuestionResponse(q.getId(),q.getText(),q.getDifficulty().name(),q.getMarks(),q.getSubject().getId(),q.getSubject().getName(),q.getOptions().stream().map(o->new AdminOptionResponse(o.getId(),o.getText(),o.isCorrect())).toList());}
}
